// p5probe_main.cpp
// GENERATED by tools/acados2ocp_pp.py from acados_ocp_nlp.json.
// Driver: warm-start, solve, dump ocp_pp.csv in the same layout as the acados
// reference (ref_acados.csv) for comparison.

#include <cstdio>

#include "ocp/solvers/acados/sqp.hpp"
#include "P5probe.hpp"

using namespace ocp;

int main()
{
    P5probe problem;

    SqpOptions opts;
    opts.print_level = 1;
    opts.max_iter = 100;
    opts.tol_stat = 1e-06;
    opts.tol_eq = 1e-06;
    opts.tol_ineq = 1e-06;
    opts.tol_comp = 1e-06;

    SqpSolver<P5probe> solver(opts);
    Solution<P5probe> sol(3);
    sol.x[0] << 0.5, 0.5;
    for (int k = 0; k < 3; ++k)
    {
        sol.u[k].setZero();
        sol.x[k + 1] = problem.cost_reference();
    }

    const Status st = solver.solve(problem, sol);
    std::printf("P5probe (generated): status=%d cost=%.12f (%d SQP iters)\n",
                static_cast<int>(sol.status), sol.cost_value,
                solver.statistics().iter);
    if (st != Status::kSolved)
    {
        std::printf("P5probe (generated): did not reach kSolved (status=%d)\n",
                    static_cast<int>(st));
    }

    // CSV dump, same layout as the acados reference (ref_acados.csv).
    const char* csv_name = "ocp_pp.csv";
    std::FILE* f = std::fopen(csv_name, "w");
    if (f == nullptr)
    {
        std::printf("FAIL: could not open %s\n", csv_name);
        return 1;
    }
    const bool solved = (sol.status == Status::kSolved);
    std::fprintf(f, "# P5probe ocp_pp\n");
    std::fprintf(f, "# nx=2 nu=2 N=3\n");
    std::fprintf(f, "# status=%d cost=%.15g\n",
                 solved ? 0 : static_cast<int>(sol.status), sol.cost_value);
    std::fprintf(f, "stage");
    for (int i = 0; i < 2; ++i)
    {
        std::fprintf(f, ",x%d", i);
    }
    for (int i = 0; i < 2; ++i)
    {
        std::fprintf(f, ",u%d", i);
    }
    std::fprintf(f, "\n");
    for (int k = 0; k <= 3; ++k)
    {
        std::fprintf(f, "%d", k);
        for (int i = 0; i < 2; ++i)
        {
            std::fprintf(f, ",%.15g", static_cast<double>(sol.x[k](i)));
        }
        if (k < 3)
        {
            for (int i = 0; i < 2; ++i)
            {
                std::fprintf(f, ",%.15g",
                             static_cast<double>(sol.u[k](i)));
            }
        }
        std::fprintf(f, "\n");
    }
    std::fclose(f);
    std::printf("wrote %s\n", csv_name);
    return 0;
}
